css:
/* VERSION: v9 | FONT = 120% OF ORIGINAL | title block smaller + lower | base 4.98mm | generated 2026-08-18 */
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
  background: #fff !important;
}

.cd-gr,
.cd-gr * {
  box-sizing: border-box;
}

.cd-gr {
  --cd-document-ink: #202020;
  --cd-document-muted: #5f6368;
  --cd-document-border: #202020;
  --cd-document-soft-border: #bdbdbd;
  --cd-document-surface: #f1f1f1;
  --cd-document-accent: #e2a2f5;

  position: relative;

  width: 210mm;
  height: 297mm;

  margin: 0;

  overflow: hidden;

  color: var(--cd-document-ink);
  background: #fff;

  font-family:
    "TH Sarabun Document",
    "Noto Sans Thai",
    "TH Sarabun New",
    "TH SarabunPSK",
    sans-serif;

  font-size: 4.98mm;
  font-weight: 400;
  line-height: 1;

  page-break-after: always;

  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-gr.last-page {
  page-break-after: auto;
}

.cd-gr p,
.cd-gr table,
.cd-gr dl,
.cd-gr dt,
.cd-gr dd {
  margin: 0;
  padding: 0;
}

.cd-gr .label-th,
.cd-gr .label-en {
  display: block;
  white-space: nowrap;
}

.cd-gr .label-th {
  font-size: 4.86mm;
  line-height: 4.14mm;
}

.cd-gr .label-en {
  font-size: 3.60mm;
  line-height: 3.06mm;
}


/* =========================================================
   HEADER
   ========================================================= */

.cd-gr .document-header {
  position: absolute;

  left: 0;
  top: 0;

  width: 210mm;
  height: 52.30mm;
}

.cd-gr .company-logo {
  position: absolute;

  left: 12.70mm;
  top: 18.56mm;

  width: 18.99mm;
  height: 7.25mm;

  object-fit: contain;
}

.cd-gr .company-name {
  position: absolute;

  left: 34.28mm;
  top: 13.62mm;

  width: 95mm;

  overflow: hidden;

  font-size: 7.44mm;
  font-weight: 700;
  line-height: 8.16mm;

  white-space: nowrap;
}

.cd-gr .company-address {
  position: absolute;

  left: 34.28mm;
  top: 22.82mm;

  width: 156mm;

  overflow: hidden;

  font-size: 4.98mm;
  line-height: 5.76mm;

  white-space: nowrap;
}

.cd-gr .company-contact {
  position: absolute;

  left: 34.28mm;
  top: 29.02mm;

  font-size: 4.98mm;
  line-height: 5.76mm;

  white-space: nowrap;
}

.cd-gr .company-tax-label,
.cd-gr .company-tax-value,
.cd-gr .company-branch {
  position: absolute;

  top: 35.63mm;

  font-size: 4.86mm;
  line-height: 6.00mm;

  white-space: nowrap;
  z-index: 3;
  background: #fff;
}

.cd-gr .company-tax-label {
  left: 34.28mm;
  width: 42.5mm;
  overflow: hidden;
}

.cd-gr .company-tax-value {
  left: 78mm;
  width: 27mm;
  overflow: hidden;
}

.cd-gr .company-branch {
  left: 106mm;
  width: 29mm;
  overflow: hidden;
  padding-right: 0.5mm;
}

.cd-gr .document-title,
.cd-gr .copy-title {
  position: absolute;

  left: 131.48mm;
  width: 59mm;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: center;
  align-items: center;

  -webkit-justify-content: center;
  justify-content: center;

  text-align: center;
  white-space: nowrap;
  z-index: 1;
}

.cd-gr .document-title {
  top: 41.10mm;

  height: 6.60mm;

  padding: 0 2mm;

  border-radius: 6mm;

  background: var(--cd-document-accent);

  font-size: 5.20mm;
  font-weight: 700;
  line-height: 1;
}

.cd-gr.is-return .document-title {
  font-size: 4.90mm;
}

.cd-gr .copy-title {
  top: 48.25mm;

  height: 5.00mm;

  font-size: 4.20mm;
  font-weight: 700;
  line-height: 1;
}


/* =========================================================
   DOCUMENT INFO BOXES
   ========================================================= */

.cd-gr .document-info {
  position: absolute;
  left: 12.70mm;
  top: 55.40mm;

  width: 184.60mm;
  height: 43.10mm;

  display: grid;
  grid-template-columns: 1.31fr 1fr;
  column-gap: 1.55mm;
}

.cd-gr .info-box {
  position: relative;
  height: 43.10mm;

  border: 0.28mm solid var(--cd-document-border);
  border-radius: 3.0mm;

  overflow: hidden;
  background: #fff;
}

.cd-gr .supplier-box {
  padding: 3.15mm 4.0mm 2.80mm 4.0mm;
}

.cd-gr .supplier-heading {
  display: flex;
  align-items: flex-start;
  min-height: 6.5mm;
}

.cd-gr .supplier-heading .compact-label {
  width: 24mm;
  flex: 0 0 24mm;
}

.cd-gr .supplier-code {
  padding-top: 0.15mm;
  font-size: 4.92mm;
  line-height: 5.40mm;
}

.cd-gr .supplier-name {
  margin-top: 0.8mm;
  max-width: 91mm;

  font-size: 4.86mm;
  line-height: 5.40mm;
  font-weight: 400;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cd-gr .supplier-address {
  margin-top: 0.65mm;
  max-width: 91mm;
  max-height: 8.0mm;

  overflow: hidden;

  font-size: 3.84mm;
  line-height: 4.14mm;
  color: #333;
}

.cd-gr .supplier-address p {
  display: inline;
}

.cd-gr .supplier-bottom-grid {
  position: absolute;
  left: 4.0mm;
  right: 4.0mm;
  bottom: 2.65mm;

  display: grid;
  grid-template-columns: 1fr 34mm;
  grid-template-rows: 7.25mm 7.25mm;
  column-gap: 4mm;
  row-gap: 0.8mm;
}

.cd-gr .field-pair {
  display: grid;
  grid-template-columns: 31mm minmax(0, 1fr);
  align-items: center;
}

.cd-gr .field-pair-date {
  grid-template-columns: 13mm minmax(0, 1fr);
}

.cd-gr .field-pair .field-label .label-th,
.cd-gr .field-pair .field-label .label-en {
  line-height: 3.18mm;
}

.cd-gr .field-pair .field-label .label-th {
  font-size: 4.26mm;
}

.cd-gr .field-pair .field-label .label-en {
  font-size: 3.30mm;
}

.cd-gr .field-value {
  min-width: 0;
  font-size: 4.74mm;
  line-height: 5.16mm;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.cd-gr .receipt-box {
  padding: 3.10mm 3.6mm 2.60mm 3.6mm;
}

.cd-gr .receipt-fields {
  position: relative;
  width: 100%;
  height: 100%;

  display: grid;
  grid-template-columns: 24.5mm 23.0mm 9.5mm minmax(0, 1fr);
  grid-template-rows: 7.4mm 7.4mm 7.4mm 7.4mm 6.5mm;
  align-items: start;
}

.cd-gr .receipt-fields > .field-label {
  padding-top: 0.15mm;
}

.cd-gr .receipt-fields > .field-label .label-th,
.cd-gr .receipt-fields > .field-label .label-en {
  line-height: 3.18mm;
}

.cd-gr .receipt-fields > .field-label .label-th {
  font-size: 4.44mm;
}

.cd-gr .receipt-fields > .field-label .label-en {
  font-size: 3.24mm;
}

.cd-gr .receipt-fields > .field-value {
  padding-top: 0.40mm;
}

.cd-gr .document-no {
  font-weight: 700;
}

.cd-gr .document-no-label { grid-column: 1; grid-row: 1; }
.cd-gr .document-no { grid-column: 2 / 5; grid-row: 1; }

.cd-gr .document-date-label { grid-column: 1; grid-row: 2; }
.cd-gr .document-date-value { grid-column: 2 / 5; grid-row: 2; }

.cd-gr .po-label { grid-column: 1; grid-row: 3; }
.cd-gr .po-value { grid-column: 2; grid-row: 3; }
.cd-gr .po-date-label { grid-column: 3; grid-row: 3; }
.cd-gr .po-date-value { grid-column: 4; grid-row: 3; }

.cd-gr .po-value {
  font-size: 4.31mm;
}

.cd-gr .po-date-value {
  font-size: 4.02mm;
}

.cd-gr .delivery-label { grid-column: 1; grid-row: 4; }
.cd-gr .delivery-value { grid-column: 2 / 5; grid-row: 4; }

.cd-gr .lr-label { grid-column: 1; grid-row: 5; }
.cd-gr .lr-value { grid-column: 2 / 5; grid-row: 5; }


/* =========================================================
   MAIN RECEIPT BODY - ONE SHARED OUTER BORDER
   ========================================================= */

.cd-gr .receipt-main {
  position: absolute;
  left: 12.70mm;
  top: 100.10mm;

  width: 184.60mm;
  height: 186.15mm;

  border: 0.28mm solid var(--cd-document-border);
  border-radius: 3.0mm;

  overflow: hidden;
  background: #fff;
}


/* =========================================================
   ITEMS TABLE
   ========================================================= */

.cd-gr .items-table {
  width: 100%;
  height: 99.15mm;

  table-layout: fixed;
  border-collapse: collapse;
  border-spacing: 0;
}

.cd-gr .items-table .col-no { width: 6.0%; }
.cd-gr .items-table .col-description { width: 54.5%; }
.cd-gr .items-table .col-qty { width: 17.0%; }
.cd-gr .items-table .col-rate { width: 12.5%; }
.cd-gr .items-table .col-amount { width: 10.0%; }

.cd-gr .items-table th,
.cd-gr .items-table td {
  border: 0;
  border-right: 0.28mm solid var(--cd-document-border);
}

.cd-gr .items-table th:last-child,
.cd-gr .items-table td:last-child {
  border-right: 0;
}

.cd-gr .items-table thead tr {
  height: 10.90mm;
}

.cd-gr .items-table thead th {
  padding: 1.2mm 1.0mm 0.80mm;

  border-bottom: 0.28mm solid var(--cd-document-border);

  text-align: center;
  vertical-align: middle;
  font-weight: 400;
}

.cd-gr .table-head-th,
.cd-gr .table-head-en {
  display: block;
  white-space: nowrap;
}

.cd-gr .table-head-th {
  font-size: 4.74mm;
  line-height: 3.90mm;
}

.cd-gr .table-head-en {
  font-size: 3.42mm;
  line-height: 2.82mm;
}


.cd-gr .items-table tbody td {
  padding: 2.2mm 1.55mm 0.8mm;
  vertical-align: top;

  font-size: 4.44mm;
  line-height: 4.86mm;
}

.cd-gr .items-table .cell-no {
  text-align: right;
  padding-right: 2.0mm;
}

.cd-gr .items-table .cell-qty {
  text-align: center;
  white-space: nowrap;
  z-index: 1;
}

.cd-gr .items-table .cell-money {
  text-align: right;
  white-space: nowrap;
  padding-right: 1.55mm;
}

.cd-gr .item-main-line {
  display: flex;
  align-items: baseline;
  gap: 2.0mm;

  min-width: 0;
}

.cd-gr .item-code {
  flex: 0 0 auto;
  white-space: nowrap;
}

.cd-gr .item-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cd-gr .item-meta-line,
.cd-gr .item-rejected-line,
.cd-gr .received-qty-note {
  margin-top: 0.55mm;

  font-size: 3.42mm;
  line-height: 3.72mm;
  color: #3f3f3f;
}

.cd-gr .item-meta-line {
  white-space: normal;
}

.cd-gr .item-meta-piece {
  display: inline-block;
  margin-right: 2.2mm;
}

.cd-gr .item-rejected-line {
  color: #222;
}

.cd-gr .received-qty-note {
  text-align: center;
  white-space: nowrap;
  z-index: 1;
}

.cd-gr .qty-uom {
  display: -webkit-flex;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 1.20mm;
  white-space: nowrap;
}

.cd-gr .qty-value,
.cd-gr .uom-text {
  display: inline;
  margin: 0;
  font-size: inherit;
  line-height: inherit;
  white-space: nowrap;
}

.cd-gr .filler-row td {
  padding: 0 !important;
}


/* =========================================================
   AUTO DENSITY FOR MORE ITEM ROWS
   ========================================================= */

.cd-gr.rows-medium .items-table tbody td {
  padding-top: 1.4mm;
  font-size: 4.14mm;
  line-height: 4.38mm;
}

.cd-gr.rows-medium .item-meta-line,
.cd-gr.rows-medium .item-rejected-line,
.cd-gr.rows-medium .received-qty-note {
  font-size: 3.18mm;
  line-height: 3.48mm;
}

.cd-gr.rows-dense .items-table tbody td {
  padding-top: 0.9mm;
  padding-bottom: 0.25mm;
  font-size: 3.72mm;
  line-height: 3.90mm;
}

.cd-gr.rows-dense .item-meta-line,
.cd-gr.rows-dense .item-rejected-line,
.cd-gr.rows-dense .received-qty-note {
  margin-top: 0.25mm;
  font-size: 2.88mm;
  line-height: 3.06mm;
}



/* =========================================================
   REMARK + TOTALS
   ========================================================= */

.cd-gr .summary-section {
  display: grid;
  grid-template-columns: 61.0% 39.0%;

  height: 52.55mm;

  border-top: 0.28mm solid var(--cd-document-border);
}

.cd-gr .remark-box {
  position: relative;
  padding: 3.0mm 3.0mm;

  border-right: 0.28mm solid var(--cd-document-border);
}

.cd-gr .summary-label .label-th {
  font-size: 4.44mm;
  line-height: 3.72mm;
}

.cd-gr .summary-label .label-en {
  font-size: 3.30mm;
  line-height: 2.82mm;
}

.cd-gr .remark-text {
  margin-top: 2.0mm;
  max-height: 38mm;
  overflow: hidden;

  font-size: 4.14mm;
  line-height: 4.62mm;
}

.cd-gr .totals-box {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.cd-gr .total-row {
  flex: 1 1 0;
  min-height: 0;

  display: grid;
  grid-template-columns: minmax(0, 1fr) 30.0mm;
  align-items: center;
}

.cd-gr .total-row + .total-row {
  border-top: 0;
}

.cd-gr .total-label {
  position: relative;
  padding: 0.45mm 2.0mm 0.25mm 3.0mm;
}

.cd-gr .total-label .label-th {
  font-size: 4.26mm;
  line-height: 3.54mm;
}

.cd-gr .total-label .label-en {
  font-size: 3.18mm;
  line-height: 2.64mm;
}

.cd-gr .total-value {
  height: 100%;

  display: flex;
  align-items: center;
  justify-content: flex-end;

  padding: 0 1.65mm 0 1mm;

  border-left: 0.28mm solid var(--cd-document-border);

  font-size: 4.56mm;
  white-space: nowrap;
}

.cd-gr .vat-label {
  padding-right: 13mm;
}

.cd-gr .vat-rate {
  position: absolute;
  right: 2.0mm;
  top: 50%;
  transform: translateY(-50%);

  font-size: 3.96mm;
  white-space: nowrap;
}

.cd-gr .grand-total-row {
  min-height: 9.3mm;
  border-top: 0.28mm solid var(--cd-document-border) !important;
}

.cd-gr .grand-total-row .total-label .label-th,
.cd-gr .grand-total-row .total-value {
  font-weight: 700;
}

.cd-gr .grand-total-row .total-value {
  font-size: 4.86mm;
}


/* =========================================================
   SIGNATURES
   ========================================================= */

.cd-gr .signature-section {
  height: 34.45mm;

  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;

  border-top: 0.28mm solid var(--cd-document-border);
}

.cd-gr .signature-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  height: 100%;
  padding-top: 3.0mm;

  text-align: center;
}

.cd-gr .signature-line {
  width: 49mm;
  height: 0;

  margin-bottom: 2.0mm;

  border-top: 0.24mm solid var(--cd-document-border);
}

.cd-gr .signature-title {
  font-size: 4.50mm;
  line-height: 5.16mm;
  white-space: nowrap;
}

.cd-gr .signature-date {
  margin-top: 2.0mm;

  font-size: 4.02mm;
  line-height: 4.44mm;
  letter-spacing: 0.15mm;
}


/* =========================================================
   PRINT SAFETY
   ========================================================= */

.cd-gr .document-info,
.cd-gr .receipt-main,
.cd-gr .items-table,
.cd-gr .summary-section,
.cd-gr .signature-section {
  page-break-inside: avoid;
}

@media print {
  .cd-gr {
    margin: 0 !important;
    box-shadow: none !important;
  }
}
